// Cache OJS + BOQ rows — weekly WIP report: open jobs + jobs completed in past 7 days (Europe/London).
const OJS_NAMES = [
  'Read Operative Job Sheet4',
  'Read Operative Job Sheet',
  'Read Operative Job Sheet1',
  'Read Operative Job Sheet5',
];
const BOQ_NAMES = [
  'Read OJS BOQ & SMV3',
  'Read OJS BOQ & SMV',
  'Read OJS BOQ & SMV1',
  'Read OJS BOQ & SMV4',
];
const WEEK_DAYS = 7;
const TZ = 'Europe/London';

function pullRows(names) {
  let best = [];
  for (let i = 0; i < names.length; i++) {
    try {
      const items = $(names[i]).all();
      if (items && items.length > best.length) {
        best = items.map(function (it) { return it.json || {}; });
      }
    } catch (e) {}
  }
  return best;
}

function jobKey(row) {
  const key = String(row['SmartForm Name'] || row.smart_form_name || row.form_name || '').trim().toUpperCase();
  return key && !/^SMARTFORM NAME$/i.test(key) ? key : '';
}

function pickCompletedDate(row) {
  const keys = Object.keys(row || {});
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    if (/^completed(\s*date)?$/i.test(String(k).trim())) {
      const v = String(row[k] ?? '').trim();
      if (v) return v;
    }
  }
  return String(row['Completed Date'] || row['Completed'] || row.completed_date || row.completed || '').trim();
}

function parseDateParts(s) {
  const t = String(s || '').trim();
  if (!t) return null;
  const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return { y: +iso[1], m: +iso[2], d: +iso[3] };
  const m = t.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (!m) return null;
  let a = parseInt(m[1], 10), b = parseInt(m[2], 10), y = parseInt(m[3], 10);
  if (y < 100) y += 2000;
  let day, mo;
  if (a > 12) { day = a; mo = b; }
  else if (b > 12) { mo = a; day = b; }
  else { day = a; mo = b; }
  return { y: y, m: mo, d: day };
}

function ymdKey(parts) {
  if (!parts) return '';
  const pad = function (n) { return n < 10 ? '0' + n : String(n); };
  return parts.y + '-' + pad(parts.m) + '-' + pad(parts.d);
}

function londonTodayParts() {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
  const bits = fmt.formatToParts(new Date());
  const out = {};
  for (let i = 0; i < bits.length; i++) {
    if (bits[i].type !== 'literal') out[bits[i].type] = bits[i].value;
  }
  return { y: +out.year, m: +out.month, d: +out.day };
}

function addDays(parts, delta) {
  const dt = new Date(Date.UTC(parts.y, parts.m - 1, parts.d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}

function isInWeeklyWindow(dateRaw) {
  const parts = parseDateParts(dateRaw);
  if (!parts) return false;
  const key = ymdKey(parts);
  const end = londonTodayParts();
  const start = addDays(end, -(WEEK_DAYS - 1));
  const startKey = ymdKey(start);
  const endKey = ymdKey(end);
  return key >= startKey && key <= endKey;
}

const allOjsRows = pullRows(OJS_NAMES);
const allBoqRows = pullRows(BOQ_NAMES);

function jobIsClosed(row) {
  const easybop = String(row['Completed'] || row.completed || '').trim();
  const js = String(row['Job Status'] || row.job_status || '').trim().toLowerCase();
  return !!easybop || js === 'completed';
}

const jobClosed = {};
const jobCompletedInWindow = {};
const jobKeysAll = new Set();
for (let i = 0; i < allOjsRows.length; i++) {
  const row = allOjsRows[i];
  const k = jobKey(row);
  if (!k) continue;
  jobKeysAll.add(k);
  if (jobIsClosed(row)) jobClosed[k] = true;
  // Recency: prefer EasyBOP `Completed`, fall back to the form `Completed Date`.
  const cd = String(row['Completed'] || row.completed || '').trim() || pickCompletedDate(row);
  if (cd && isInWeeklyWindow(cd)) jobCompletedInWindow[k] = true;
}

// Include a job if it is still open (WIP / in jeopardy / OJS scope complete awaiting date)
// or if it was completed within the last 7 days.
const weeklyJobKeys = new Set();
jobKeysAll.forEach(function (k) {
  if (!jobClosed[k] || jobCompletedInWindow[k]) weeklyJobKeys.add(k);
});

const ojsRows = allOjsRows.filter(function (row) {
  const k = jobKey(row);
  return k && weeklyJobKeys.has(k);
});

const boqRows = allBoqRows.filter(function (row) {
  const k = jobKey(row);
  return k && weeklyJobKeys.has(k);
});

const sd = $getWorkflowStaticData('global');
sd._reportOjsRows = ojsRows;
sd._reportBoqRows = boqRows;

const end = londonTodayParts();
const start = addDays(end, -(WEEK_DAYS - 1));
const pad = function (n) { return n < 10 ? '0' + n : String(n); };
const weekLabel = pad(start.d) + '/' + pad(start.m) + '/' + start.y + ' – ' + pad(end.d) + '/' + pad(end.m) + '/' + end.y;

return [{
  json: {
    ojs_rows_stored: ojsRows.length,
    boq_rows_stored: boqRows.length,
    ojs_rows_total: allOjsRows.length,
    weekly_job_count: weeklyJobKeys.size,
    week_window_label: weekLabel,
  },
}];

// Reads cached rows from static data — set by Store sheet rows node upstream.
const sd = $getWorkflowStaticData('global');
const ojsRows = sd._reportOjsRows || [];
const boqRows = sd._reportBoqRows || [];
const storeMeta = (function () {
  try { return $('Store sheet rows1').first().json || {}; } catch (e) { return {}; }
})();
const dateSlug = new Date().toISOString().slice(0, 10);
const weekLabel = storeMeta.week_window_label || '';
const weeklyJobCount = storeMeta.weekly_job_count != null ? storeMeta.weekly_job_count : null;
const ojsRowsTotal = storeMeta.ojs_rows_total != null ? storeMeta.ojs_rows_total : ojsRows.length;

function jobKey(row) {
  const key = String(row['SmartForm Name'] || row.smart_form_name || row.form_name || '').trim().toUpperCase();
  return key && !/^SMARTFORM NAME$/i.test(key) ? key : '';
}

const jeopardyJobs = new Set();
const nextApptJobs = new Set();
const managerJobs = new Set();

for (let i = 0; i < ojsRows.length; i++) {
  const row = ojsRows[i];
  const key = jobKey(row);
  if (!key) continue;
  const flag = String(row['In Jeopardy'] || row.in_jeopardy || '').trim().toLowerCase();
  if (flag === 'yes' || flag === 'true' || flag === '1') {
    jeopardyJobs.add(key);
    const jt = String(row['Jeopardy Type'] || row.jeopardy_type || '').trim().toLowerCase();
    if (jt === 'next_appointment_needed') nextApptJobs.add(key);
    if (jt === 'manager_review') managerJobs.add(key);
  }
}

return [{
  json: {
    ojs_rows: ojsRows,
    boq_rows: boqRows,
    ojs_rows_read: ojsRows.length,
    boq_rows_read: boqRows.length,
    jeopardy_job_count: jeopardyJobs.size,
    next_appointment_needed_count: nextApptJobs.size,
    manager_review_count: managerJobs.size,
    pdf_filename: 'wip-report-weekly-' + dateSlug + '.pdf',
    week_window_label: weekLabel,
    weekly_job_count: weeklyJobCount,
    ojs_rows_total: ojsRowsTotal,
  },
}];

function esc(t) {
  return String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const built = $('Build report payload1').first().json || {};
const http = $input.first();
const pdf = http.binary && http.binary.report_pdf;
if (!pdf) {
  throw new Error('PDF not returned — check API is running and ngrok URL is correct');
}

const reportDate = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' }).replace(',', '');
const sheetUrl = 'https://docs.google.com/spreadsheets/d/1mkklLpvi8klaN4Zo4D_cBrb95PGQ4NbUvtTAvLI4CII/edit';
const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';

const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="640" style="background:#fff;border-radius:8px;">',
  '<tr><td style="background:#145c63;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway Group"></td></tr>',
  '<tr><td style="padding:24px;"><h2 style="margin:0;color:#145c63;">Stage 6 — WIP Report</h2>',
  '<p style="color:#56616b;">Generated: <strong style="color:#17212b;">' + esc(reportDate) + '</strong> (Europe/London)</p>',
  '<p style="color:#444;font-size:14px;">The attached PDF uses <strong>BCC Tracker Status</strong> sections: <strong>WIP</strong>, <strong>Awaiting next appointment</strong>, <strong>Manager review needed</strong>, and <strong>Awaiting handover info</strong>.</p>',
  '<p style="color:#56616b;font-size:13px;">OJS rows: ' + esc(built.ojs_rows_read) + ' · BOQ rows: ' + esc(built.boq_rows_read) +
    ' · Awaiting next appointment: ' + esc(built.next_appointment_needed_count != null ? built.next_appointment_needed_count : '—') +
    ' · Manager review needed: ' + esc(built.manager_review_count != null ? built.manager_review_count : '—') + '</p></td></tr>',
  '<tr><td style="padding:0 24px 24px;text-align:center;">',
  '<a href="' + sheetUrl + '" style="display:inline-block;margin:6px;padding:10px 18px;background:#145c63;color:#fff;text-decoration:none;border-radius:4px;font-size:13px;">Open Stage 6 sheet</a>',
  '</td></tr>',
  '<tr><td style="background:#f7fafb;padding:16px;text-align:center;font-size:11px;color:#56616b;">Jeffway Group · Stage 6 WIP report automation</td></tr>',
  '</table></td></tr></table></body></html>',
].join('');

const filename = built.pdf_filename || 'wip-report.pdf';

return [{
  json: {
    _alert_subject: 'Stage 6 WIP Report — ' + reportDate,
    _alert_html: html,
    pdf_filename: filename,
    ojs_rows_read: built.ojs_rows_read,
    boq_rows_read: built.boq_rows_read,
    jeopardy_job_count: built.jeopardy_job_count,
    next_appointment_needed_count: built.next_appointment_needed_count,
    manager_review_count: built.manager_review_count,
  },
  binary: {
    report_pdf: Object.assign({}, pdf, { fileName: filename }),
  },
}];

const prep = (function () {
  try { return $('Prepare Gmail1').first().json || {}; } catch (e) { return {}; }
})();

return [{
  json: {
    ok: true,
    message: 'WIP report PDF emailed to hamza@eynvision.com',
    subject: prep._alert_subject || '',
    pdf_filename: prep.pdf_filename || '',
    ojs_rows_read: prep.ojs_rows_read,
    boq_rows_read: prep.boq_rows_read,
    jeopardy_job_count: prep.jeopardy_job_count,
    next_appointment_needed_count: prep.next_appointment_needed_count,
    manager_review_count: prep.manager_review_count,
    sent_at: new Date().toISOString(),
  },
}];
